static partial class App {
 static int ArrowTest(string[] args){string root=Path.GetFullPath(args[1]);Directory.CreateDirectory(root);int checkedFiles=0,checkedFrames=0;foreach(int theme in Enumerable.Range(8,Art.Names.Length-8))foreach(int size in new[]{32,48,64,96})foreach(string role in new[]{"Arrow","Hand","Help","Pin","Person"}){int count=Art.IsAnimated(theme)?16:1;var frames=new List<byte[]>();for(int frame=0;frame<count;frame++){using(var image=Art.Draw(theme,role,size,frame,count)){var tip=Art.Hotspot(theme,role,size);Assert(image.GetPixel(tip.X,tip.Y).A>0,"hotspot lies on triangle tip");var sample=image.GetPixel((int)Math.Round(8*size/64f),(int)Math.Round(8*size/64f));var expected=ColorTranslator.FromHtml(Art.Colors[theme]);Assert(Math.Abs(sample.R-expected.R)<=2&&Math.Abs(sample.G-expected.G)<=2&&Math.Abs(sample.B-expected.B)<=2,"triangle matches skin palette");frames.Add(Art.Cur(image,tip.X,tip.Y));}}byte[] data=count==1?frames[0]:Art.Ani(frames,5);string path=Path.Combine(root,theme+"-"+size+"-"+role+(count==1?".cur":".ani"));File.WriteAllBytes(path,data);Native.Validate(path);checkedFiles++;var encoded=CursorFrames(data);Assert(encoded.Count==count,"animation frames retained");foreach(byte[] cursor in encoded){Assert(BitConverter.ToUInt16(cursor,10)==(ushort)Math.Round(3*size/64f)&&BitConverter.ToUInt16(cursor,12)==(ushort)Math.Round(3*size/64f),"encoded arrow-tip hotspot");checkedFrames++;}}
  var log=new List<string>{"PASS: "+checkedFiles+" native CUR/ANI variants load across 46 fun skins, five fun roles and four sizes.","PASS: all "+checkedFrames+" encoded frames have fixed top-left triangle-tip hotspots on visible arrow pixels."};if(args.Length>2){string priorRoot=Path.GetFullPath(args[2]);var json=new System.Web.Script.Serialization.JavaScriptSerializer();var previous=json.Deserialize<Preferences>(File.ReadAllText(Path.Combine(priorRoot,"settings.json")));var oldFiles=previous.Skins.Where(s=>s.Builtin>=8&&s.Builtin<16).Select(s=>s.Roles["Arrow"]).ToList();Assert(oldFiles.Count==8&&oldFiles.All(File.Exists),"prior cache fixture");var upgraded=new Store(priorRoot,false);foreach(var skin in upgraded.Pref.Skins.Where(s=>s.Builtin>=8)){Assert(skin.Roles["Arrow"].Contains("builtin-v4"),"cache revision migrated");foreach(var cursor in CursorFrames(File.ReadAllBytes(skin.Roles["Arrow"])))Assert(BitConverter.ToUInt16(cursor,10)==(ushort)Math.Round(3*upgraded.Pref.Size/64f),"cached hotspot upgraded");}Assert(oldFiles.All(File.Exists),"old caches retained for undo");log.Add("PASS: existing 1.2 cache migrates to arrow version, preserving old files for backup references.");}File.WriteAllLines(Path.Combine(root,"arrow-results.txt"),log,Encoding.UTF8);return 0;}
 static List<byte[]> CursorFrames(byte[] data){var frames=new List<byte[]>();if(data.Length>6&&data[2]==2&&data[3]==0){frames.Add(data);return frames;}for(int pos=12;pos+8<=data.Length;){int length=BitConverter.ToInt32(data,pos+4);Assert(length>=0&&(long)pos+8+length<=data.Length,"valid RIFF chunk");if(Encoding.ASCII.GetString(data,pos,4)=="LIST"&&length>=4&&Encoding.ASCII.GetString(data,pos+8,4)=="fram"){for(int inner=pos+12;inner+8<=pos+8+length;){int size=BitConverter.ToInt32(data,inner+4);Assert(size>=0&&(long)inner+8+size<=pos+8+length,"valid icon chunk");if(Encoding.ASCII.GetString(data,inner,4)=="icon"){var frame=new byte[size];Buffer.BlockCopy(data,inner+8,frame,0,size);frames.Add(frame);}inner+=8+size+(size%2);}}pos+=8+length+(length%2);}Assert(frames.Count>0,"native cursor frames found");return frames;}
 static void Pump(){Application.DoEvents();Application.DoEvents();}
 static int ReliabilityTest(string directory){Directory.CreateDirectory(directory);ErrorLog.DirectoryPath=Path.Combine(directory,"logs");var errors=new List<Exception>();Theme.ErrorSink=errors.Add;var log=new List<string>();var store=new Store(Path.Combine(directory,"data"),false);store.Pref.Hotkeys=false;store.Pref.Tray=false;
  try{using(var main=new MainForm(store)){main.Show();Pump();int actions=0;for(int i=0;i<40;i++){
    var menu=main.CreateToolsMenu();menu.Show(main,new Point(15,15));menu.Items[0].PerformClick();Pump();Assert(menu.IsDisposed,"transient menu deferred cleanup");actions++;
    menu=main.SortMenu;menu.Show(main,new Point(15,15));menu.Items[i%4].PerformClick();Pump();Assert(!menu.IsDisposed,"persistent sort menu remains alive");actions++;
    menu=main.RoleMenu;menu.Show(main,new Point(15,15));menu.Items[i%menu.Items.Count].PerformClick();main.ShowCategory("趣味造型");Pump();Assert(menu.IsDisposed,"rebuilt role menu disposed after dispatch");actions++;
    menu=main.CreateToolsMenu();menu.Show(main,new Point(15,15));menu.Items.OfType<ToolStripMenuItem>().First(x=>x.Text.StartsWith("清空搜索")).PerformClick();Pump();actions++;
   }Assert(errors.Count==0,"menu UI errors");log.Add("PASS: 160 real menu clicks, close/reopen, sort, rotation, filter and selection rebuilds; no disposed-menu exception.");
   int count=store.Pref.Skins.Count;var copy=main.CreateToolsMenu();copy.Show(main,new Point(15,15));copy.Items[1].PerformClick();Pump();Assert(store.Pref.Skins.Count==count+1,"actual clone menu action");log.Add("PASS: copy action runs after drop-down dismissal and rebuilds detail view safely.");
   var clone=store.Pref.Skins.Last();using(var mapping=new MappingDialog(store,clone)){mapping.Show();mapping.Controls.OfType<TextBox>().First().Text="角色映射验证";var combos=Descendants(mapping).OfType<ComboBox>().ToList();combos[1].SelectedIndex=0;mapping.Controls.OfType<Button>().First(b=>b.Text=="保存映射").PerformClick();Assert(mapping.DialogResult==DialogResult.OK,"mapping save button");mapping.Close();}Assert(clone.Name=="角色映射验证"&&!clone.Roles.ContainsKey("Hand")&&clone.Roles.ContainsKey("Arrow"),"mapping values saved");store.Save();log.Add("PASS: mapping dialog saves rename and partial role selection.");
   using(var settings=new SettingsDialog(store)){settings.Show();settings.Controls.OfType<CheckBox>().First(c=>c.Text.StartsWith("启动时应用")).Checked=false;settings.Controls.OfType<Button>().First(b=>b.Text=="保存设置").PerformClick();Assert(settings.DialogResult==DialogResult.OK&&!store.Pref.ApplyOnStartup,"settings actual save");settings.Close();}log.Add("PASS: settings dialog saves startup behavior without touching an unchanged autostart switch.");
   main.TestMissingSkin(new Skin{Id=Guid.NewGuid().ToString("N"),Name="文件丢失",Roles=new Dictionary<string,string>{{"Arrow",Path.Combine(directory,"missing.cur")}}});Pump();main.TestMissingSkin(new Skin{Id=Guid.NewGuid().ToString("N"),Name="空映射"});Pump();Assert(errors.Count==0,"missing preview errors");log.Add("PASS: missing cursor files and empty mappings keep UI usable and disable Apply.");
   string protectedExport=Path.Combine(directory,"keep-existing.zip");File.WriteAllText(protectedExport,"existing backup");bool exportRejected=false;try{store.Export(new Skin{Roles=new Dictionary<string,string>{{"Arrow",Path.Combine(directory,"missing-export.cur")}}},protectedExport);}catch(IOException){exportRejected=true;}Assert(exportRejected&&File.ReadAllText(protectedExport)=="existing backup","failed export preserves target");log.Add("PASS: failed exports preserve existing backup files.");
   main.Close();Pump();Assert(!main.IsDisposed&&!main.Visible,"X hides main form to tray");main.ExitApplication();Pump();Assert(main.IsDisposed,"explicit exit ends main form");}
   using(var owner=new Form()){owner.Show();var menu=new SafeMenu(owner,true);menu.Action("close",()=>owner.Close());menu.Show(owner,new Point(1,1));menu.Items[0].PerformClick();Pump();Assert(owner.IsDisposed&&menu.IsDisposed,"exit from active menu");}log.Add("PASS: exiting from a menu callback disposes owner and menu safely.");
   TestDownloadLifecycle(store,directory);log.Add("PASS: downloader parses page, imports animated/static pair, cancels while closing and tolerates invalid URL.");
   string settingsFile=Path.Combine(store.Root,"settings.json");File.WriteAllText(settingsFile,"invalid json");var recovered=new Store(store.Root,false);Assert(recovered.Pref.Skins.Count==Art.Names.Length&&Directory.GetFiles(store.Root,"settings-recovery-*.json").Length==1,"corrupt settings recovery");File.WriteAllText(settingsFile,"{\"Size\":-5,\"RotationMinutes\":0,\"Skins\":null,\"ThemeId\":null,\"Sort\":null}");var normalized=new Store(store.Root,false);Assert(normalized.Pref.Size==48&&normalized.Pref.RotationMinutes==1&&normalized.Pref.Tray&&normalized.Pref.RestoreOnExit,"invalid setting normalization");log.Add("PASS: corrupt settings preserved for recovery; null collections, invalid dimensions and legacy shutdown policy normalized.");
   Assert(errors.Count==0,"unexpected UI errors");File.WriteAllLines(Path.Combine(directory,"reliability-results.txt"),log,Encoding.UTF8);return 0;
  }finally{Theme.ErrorSink=null;}
 }
 static void TestDownloadLifecycle(Store store,string directory){
  using(var d=new DownloadDialog(store)){d.Show();d.TestTransport=(uri,limit,token)=>{string url=uri.AbsoluteUri;if(url.EndsWith("windows-cursor/"))return Task.FromResult(File.ReadAllBytes(store.Pref.Skins[4].Roles["Arrow"]));if(url.EndsWith("windows-pointer/"))return Task.FromResult(File.ReadAllBytes(store.Pref.Skins[0].Roles["Hand"]));return Task.FromResult(Encoding.UTF8.GetBytes("<html><a href='/cursor/test/downloads/windows-cursor/'>a</a><a href='/cursor/test/downloads/windows-pointer/'>b</a></html>"));};var task=d.TestDownload("https://sweezy-cursors.com/cursor/test/");while(!task.IsCompleted)Pump();var paths=task.GetAwaiter().GetResult();var skin=store.Import(paths,48,0,0);Assert(skin.Animated&&skin.Roles.ContainsKey("Hand"),"HTTP page flow imported");d.Close();}
  using(var d=new DownloadDialog(store)){d.Show();d.TestTransport=(uri,limit,token)=>{var tcs=new TaskCompletionSource<byte[]>();token.Register(()=>tcs.TrySetCanceled());return tcs.Task;};var task=d.TestDownload("https://sweezy-cursors.com/cursor/test/");d.Close();while(!task.IsCompleted)Pump();bool canceled=false;try{task.GetAwaiter().GetResult();}catch(OperationCanceledException){canceled=true;}Assert(canceled&&d.IsDisposed,"download close cancellation");Assert(!Directory.Exists(d.TempDirectory),"canceled download cleanup");}
  using(var d=new DownloadDialog(store)){d.Show();var task=d.TestDownload("not-a-url");while(!task.IsCompleted)Pump();bool rejected=false;try{task.GetAwaiter().GetResult();}catch(InvalidDataException){rejected=true;}Assert(rejected,"invalid URL handled");d.Close();}
 }
 static int LifecycleTest(string directory){Directory.CreateDirectory(directory);var store=new Store(Path.Combine(directory,"data"));store.Pref.Hotkeys=false;store.Pref.Tray=false;store.Pref.Rotate=false;var baseline=store.Capture();store.Write("emergency-baseline.json",baseline);bool hadRun;object runValue=null;RegistryValueKind runKind=RegistryValueKind.String;using(var key=Registry.CurrentUser.OpenSubKey(StartupService.RunKey)){hadRun=key!=null&&key.GetValueNames().Contains(StartupService.ValueName);if(hadRun){runValue=key.GetValue(StartupService.ValueName,null,RegistryValueOptions.DoNotExpandEnvironmentNames);runKind=key.GetValueKind(StartupService.ValueName);}}var log=new List<string>();try{
   StartupService.Set(false);Assert(!StartupService.Enabled,"autostart off");StartupService.Set(true);Assert(StartupService.Enabled,"autostart on");using(var key=Registry.CurrentUser.OpenSubKey(StartupService.RunKey))Assert(Convert.ToString(key.GetValue(StartupService.ValueName))==StartupService.Command(Application.ExecutablePath),"quoted autostart command");StartupService.Set(false);Assert(!StartupService.Enabled,"autostart off again");log.Add("PASS: actual HKCU autostart on/off and quoted --tray command verified.");
   store.Apply(store.Pref.Skins[12]);using(var form=new MainForm(store)){form.Show();form.TestStartupSwitch();form.Close();Pump();Assert(!form.IsDisposed&&!form.Visible,"X always hides to tray");Assert(store.Pref.Active==store.Pref.Skins[12].Id,"tray retains active cursor");form.ExitApplication();Pump();Assert(form.IsDisposed,"explicit exit");}AssertDefault(store);Assert(store.Pref.LastSkin==store.Pref.Skins[12].Id&&string.IsNullOrEmpty(store.Pref.Active),"last skin retained while active cleared");log.Add("PASS: visible autostart switch enables/disables actual Run entry; X hides to tray; explicit exit restores Windows default.");
   store.Pref.Tray=true;store.Apply(store.Pref.Skins[4]);using(var form=new MainForm(store)){form.Show();form.Close();Assert(!form.IsDisposed&&!form.Visible,"explicit tray mode remains running");Assert(store.Capture().Values.First(e=>e.Name=="Arrow").Value==store.Pref.Skins[4].Roles["Arrow"],"tray mode retains skin");form.ExitApplication();Pump();Assert(form.IsDisposed,"explicit tray exit");}AssertDefault(store);log.Add("PASS: optional close-to-tray keeps running; explicit exit restores Windows default.");
   store.Pref.Tray=false;store.Apply(store.Pref.Skins[8]);using(var form=new MainForm(store)){form.Show();form.TestTrayExit();Pump();Assert(form.IsDisposed,"tray menu exit");}AssertDefault(store);log.Add("PASS: actual tray-menu exit is deferred safely and restores Windows default.");
   store.Pref.ApplyOnStartup=true;store.Pref.LastSkin=store.Pref.Skins[12].Id;store.Save();using(var form=new MainForm(store)){form.Show();form.RestoreLastSkin();App.WaitSize(form);Assert(store.Capture().Values.First(e=>e.Name=="Arrow").Value==store.Pref.Skins[12].Roles["Arrow"],"apply remembered skin on startup");form.TestHotkeysAndRotation(log);form.ExitApplication();Pump();}AssertDefault(store);log.Add("PASS: remembered skin reapplies on startup; subsequent exit resets default.");
   using(var process=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--run-smoke \""+store.Root+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){if(!process.WaitForExit(45000)){process.Kill();process.WaitForExit();throw new Exception("Runtime process smoke test timed out");}Assert(process.ExitCode==0,"normal runtime process exit code");}Assert(File.ReadAllText(Path.Combine(store.Root,"runtime-smoke.txt"))==store.Pref.Skins[12].Id,"real process startup applied skin");AssertDefault(store);log.Add("PASS: complete application process starts, applies last skin, closes and resets default without framework error.");
  }finally{store.SetSnapshot(baseline);using(var key=Registry.CurrentUser.CreateSubKey(StartupService.RunKey)){if(hadRun)key.SetValue(StartupService.ValueName,runValue,runKind);else key.DeleteValue(StartupService.ValueName,false);}log.Add("FINALLY: original desktop scheme and original autostart registration restored.");File.WriteAllLines(Path.Combine(directory,"lifecycle-results.txt"),log,Encoding.UTF8);}return 0;}
 static void AssertDefault(Store store){var current=store.Capture();foreach(var role in Store.Roles)Assert(current.Values.First(e=>e.Name==role).Value=="","default role "+role);Assert(current.Values.First(e=>e.Name=="").Value=="","default scheme name");}
}
public partial class MainForm {
 internal void TestMissingSkin(Skin skin){SelectSkin(skin);if(apply.Enabled)throw new Exception("Apply must be disabled for missing files");}
 internal void TestTrayExit(){var menu=tray.ContextMenuStrip;menu.Show(this,new Point(5,5));menu.Items[menu.Items.Count-1].PerformClick();}
 internal void TestStartupSwitch(){var click=typeof(Button).GetMethod("OnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);click.Invoke(startupSwitch,new object[]{EventArgs.Empty});if(!StartupService.Enabled||!startupOn)throw new Exception("Autostart UI did not turn on");click.Invoke(startupSwitch,new object[]{EventArgs.Empty});if(StartupService.Enabled||startupOn)throw new Exception("Autostart UI did not turn off");}
 internal void TestHotkeysAndRotation(List<string> log){store.Pref.Hotkeys=true;BindKeys();log.Add(hkOk?"PASS: all three global hotkeys registered with Windows.":"NOTE: at least one global hotkey is occupied by another program on this host.");string before=store.Pref.Active;var message=Message.Create(Handle,0x312,new IntPtr(2),IntPtr.Zero);WndProc(ref message);App.WaitSize(this);if(store.Pref.Active==before)throw new Exception("Random hotkey did not change skin");message=Message.Create(Handle,0x312,new IntPtr(1),IntPtr.Zero);WndProc(ref message);if(!string.IsNullOrEmpty(store.Pref.Active))throw new Exception("Restore hotkey did not reset active state");Hide();message=Message.Create(Handle,0x312,new IntPtr(3),IntPtr.Zero);WndProc(ref message);if(!Visible)throw new Exception("Show hotkey did not display window");store.Pref.Hotkeys=false;BindKeys();log.Add("PASS: WM_HOTKEY routes random, original-scheme restore and show-window actions.");
  store.Pref.FavoritesOnly=false;store.Pref.Rotate=true;before=store.Pref.Active;nextRotate=DateTime.Now.AddSeconds(-2);var deadline=DateTime.Now.AddSeconds(3);while(store.Pref.Active==before&&DateTime.Now<deadline){Application.DoEvents();Thread.Sleep(10);}store.Pref.Rotate=false;if(store.Pref.Active==before)throw new Exception("Rotation timer did not apply a skin");log.Add("PASS: real UI rotation timer applies a different skin.");
  foreach(var s in store.Pref.Skins)s.Favorite=false;var chosen=store.Pref.Skins[9];chosen.Favorite=true;store.Pref.FavoritesOnly=true;store.Apply(store.Pref.Skins[0]);RandomSkin();App.WaitSize(this);if(store.Pref.Active!=chosen.Id)throw new Exception("Favorite-only random selection escaped favorites");store.Pref.FavoritesOnly=false;log.Add("PASS: favorite-only random selection respects the collection.");store.Pref.LastSkin=store.Pref.Skins[12].Id;store.Save();
 }
}
